template:
% 参数由系统自动注入；斜四棱柱 ABCD-A₁B₁C₁D₁，匹配高考题图视角
% ABCD 为下底面平行四边形，A₁B₁C₁D₁ 为上底面
% AA₁、BB₁、CC₁、DD₁ 为互相平行的斜侧棱
% 实线：可见棱；虚线：被遮挡棱（AD、CD、DD₁）
% 视觉归一化：把图形最长外接尺寸缩放到约 6 个坐标单位
% ==========================================================
% 底面顶点坐标计算
% ==========================================================
% 下底面：A(0,0) 原点，B 在 x 轴正方向
\pgfmathsetmacro{\Ax}{0}
\pgfmathsetmacro{\Ay}{0}
\pgfmathsetmacro{\Bx}{\basex}
\pgfmathsetmacro{\By}{0}
% D 在 A 的后上方，AD 为侧棱
\pgfmathsetmacro{\Dx}{0.55 * \basey}
\pgfmathsetmacro{\Dy}{0.65 * \basey}
% C 由 B 平移 AD 向量得到
\pgfmathsetmacro{\Cx}{\Bx + \Dx}
\pgfmathsetmacro{\Cy}{\By + \Dy}
% ==========================================================
% 上底面顶点：整体沿侧棱向量 (slantx, slanty) 平移
% ==========================================================
\pgfmathsetmacro{\Apx}{\Ax + \slantx}
\pgfmathsetmacro{\Apy}{\Ay + \slanty}
\pgfmathsetmacro{\Bpx}{\Bx + \slantx}
\pgfmathsetmacro{\Bpy}{\By + \slanty}
\pgfmathsetmacro{\Dpx}{\Dx + \slantx}
\pgfmathsetmacro{\Dpy}{\Dy + \slanty}
\pgfmathsetmacro{\Cpx}{\Cx + \slantx}
\pgfmathsetmacro{\Cpy}{\Cy + \slanty}
% ==========================================================
% 辅助点坐标：直接公式计算，不依赖 calc 库，彻底避免跑位
% ==========================================================
% E：AB 中点
\pgfmathsetmacro{\Ex}{0.5 * \basex}
\pgfmathsetmacro{\Ey}{0}
% F：AA₁ 中点
\pgfmathsetmacro{\Fx}{0.5 * \slantx}
\pgfmathsetmacro{\Fy}{0.5 * \slanty}
% G：A₁B₁ 中点
\pgfmathsetmacro{\Gx}{0.5 * \basex + \slantx}
\pgfmathsetmacro{\Gy}{\slanty}
% ==========================================================
% 视觉归一化
% ==========================================================
\pgfmathsetmacro{\xmin}{min(\Ax,\Bx,\Cx,\Dx,\Apx,\Bpx,\Cpx,\Dpx)}
\pgfmathsetmacro{\xmax}{max(\Ax,\Bx,\Cx,\Dx,\Apx,\Bpx,\Cpx,\Dpx)}
\pgfmathsetmacro{\ymin}{min(\Ay,\By,\Cy,\Dy,\Apy,\Bpy,\Cpy,\Dpy)}
\pgfmathsetmacro{\ymax}{max(\Ay,\By,\Cy,\Dy,\Apy,\Bpy,\Cpy,\Dpy)}
\pgfmathsetmacro{\figscale}{6 / max(\xmax-\xmin, \ymax-\ymin)}
% ==========================================================
% 开始绘图
% ==========================================================
\begin{tikzpicture}[
    scale=\figscale,
    every node/.style={
        font=\small,
        fill=none,
        inner sep=1.5pt
    }
]
    % ======================================================
    % 八个顶点
    % ======================================================
    \coordinate (A)  at (\Ax,\Ay);
    \coordinate (B)  at (\Bx,\By);
    \coordinate (C)  at (\Cx,\Cy);
    \coordinate (D)  at (\Dx,\Dy);
    \coordinate (Ap) at (\Apx,\Apy);
    \coordinate (Bp) at (\Bpx,\Bpy);
    \coordinate (Cp) at (\Cpx,\Cpy);
    \coordinate (Dp) at (\Dpx,\Dpy);
    % 辅助点预定义
    \coordinate (E)  at (\Ex,\Ey);
    \coordinate (F)  at (\Fx,\Fy);
    \coordinate (G)  at (\Gx,\Gy);

    % ======================================================
    % 下底面棱
    % ======================================================
    \draw[thick] (A) -- (B);
    \draw[thick] (B) -- (C);
    \draw[dashed,thick] (C) -- (D);
    \ifnum\showhidden>0
        \draw[dashed,thick] (D) -- (A);
    \else
        \draw[thick] (D) -- (A);
    \fi

    % ======================================================
    % 上底面棱（全部可见，实线）
    % ======================================================
    \draw[thick] (Ap) -- (Bp);
    \draw[thick] (Bp) -- (Cp);
    \draw[thick] (Cp) -- (Dp);
    \draw[thick] (Dp) -- (Ap);

    % ======================================================
    % 四条斜侧棱
    % ======================================================
    \draw[thick] (A) -- (Ap);
    \draw[thick] (B) -- (Bp);
    \draw[thick] (C) -- (Cp);
    \ifnum\showhidden>0
        \draw[dashed,thick] (D) -- (Dp);
    \else
        \draw[thick] (D) -- (Dp);
    \fi

    % ======================================================
    % 辅助线：上下底面对角线
    % ======================================================
    \ifnum\showaux>0
        \draw[dashed,thick] (A) -- (C);
        \draw[dashed,thick] (B) -- (D);
        \draw[dashed,thick] (Ap) -- (Cp);
        \draw[dashed,thick] (Bp) -- (Dp);
    \fi

    % ======================================================
    % 顶点标签
    % ======================================================
    \ifnum\showverts>0
        \node[below left=3pt] at (A) {$A$};
        \node[below right=3pt] at (B) {$B$};
        \node[right=4pt] at (C) {$C$};
        \node[left=4pt] at (D) {$D$};
        \node[left=4pt] at (Ap) {$A_1$};
        \node[right=4pt] at (Bp) {$B_1$};
        \node[above right=4pt] at (Cp) {$C_1$};
        \node[above left=4pt] at (Dp) {$D_1$};
    \fi

    % ======================================================
    % 辅助点 E、F、G
    % ======================================================
    \ifnum\showpoints>0
        \node[circle, fill=black, inner sep=0.5pt] at (E) {};
        \node[circle, fill=black, inner sep=0.5pt] at (F) {};
        \node[circle, fill=black, inner sep=0.5pt] at (G) {};
        \node[below=3pt] at (E) {$E$};
        \node[left=3pt] at (F) {$F$};
        \node[above=3pt] at (G) {$G$};
    \fi
\end{tikzpicture}
